package com.customui.backgrounds;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;

/** A small, independent renderer so image scaling can be unit tested without RuneLite. */
final class BackgroundImageRenderer
{
    private BackgroundImageRenderer()
    {
    }

    /**
     * Renders a complete opaque sprite at the target dimensions. The image is
     * alpha-blended over the original interface sprite (when available).
     * Borders and chat tabs are intentionally not replaced.
     */
    static BufferedImage render(BufferedImage original, BufferedImage photo, int width, int height,
                                int insetLeft, int insetTop, int insetRight, int insetBottom,
                                int opacityPercent, ScalingMode scaling, Color fallback)
    {
        BufferedImage output = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = output.createGraphics();
        try
        {
            // Retain native sprite transparency (especially in modern gameframes).
            // Only use a solid fallback when the client artwork has not loaded yet.
            if (original == null)
            {
                g.setColor(fallback);
                g.fillRect(0, 0, width, height);
            }
            if (original != null)
            {
                // If the native sprite tiles (e.g. 32x32 resizable inventory),
                // tile it under the personal image so empty edges remain intact.
                for (int y = 0; y < height; y += original.getHeight())
                {
                    for (int x = 0; x < width; x += original.getWidth())
                    {
                        g.drawImage(original, x, y, null);
                    }
                }
            }

            int x = insetLeft;
            int y = insetTop;
            int w = Math.max(1, width - insetLeft - insetRight);
            int h = Math.max(1, height - insetTop - insetBottom);
            g.setClip(x, y, w, h);
            g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER,
                Math.min(100, Math.max(0, opacityPercent)) / 100f));
            g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
            g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);

            if (scaling == ScalingMode.STRETCH)
            {
                g.drawImage(photo, x, y, w, h, null);
            }
            else
            {
                double ratioX = w / (double) photo.getWidth();
                double ratioY = h / (double) photo.getHeight();
                double ratio = scaling == ScalingMode.FIT ? Math.min(ratioX, ratioY) : Math.max(ratioX, ratioY);
                int scaledW = Math.max(1, (int) Math.round(photo.getWidth() * ratio));
                int scaledH = Math.max(1, (int) Math.round(photo.getHeight() * ratio));
                g.drawImage(photo, x + (w - scaledW) / 2, y + (h - scaledH) / 2, scaledW, scaledH, null);
            }
        }
        finally
        {
            g.dispose();
        }
        return output;
    }
}

package com.customui.backgrounds;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(PersonalUiBackgroundsConfig.GROUP)
public interface PersonalUiBackgroundsConfig extends Config
{
    String GROUP = "personalUiBackgrounds";

    @ConfigSection(name = "Inventory", description = "Image behind inventory items and other side tabs", position = 0)
    String INVENTORY = "inventory";

    @ConfigSection(name = "Chatbox", description = "Image behind the chat text", position = 1)
    String CHATBOX = "chatbox";

    @ConfigItem(keyName = "inventoryEnabled", name = "Enable inventory image", description = "Apply a custom image to the side panel background", section = INVENTORY, position = 0)
    default boolean inventoryEnabled()
    {
        return true;
    }

    @ConfigItem(keyName = "inventoryImagePath", name = "Inventory image file", description = "Full path to a PNG or JPEG file (or use the plugin's Browse panel)", section = INVENTORY, position = 1)
    default String inventoryImagePath()
    {
        return "";
    }

    @Range(min = 0, max = 100)
    @ConfigItem(keyName = "inventoryOpacity", name = "Inventory image strength", description = "Percent image blended onto the game's original background", section = INVENTORY, position = 2)
    default int inventoryOpacity()
    {
        return 85;
    }

    @ConfigItem(keyName = "inventoryScale", name = "Inventory image scaling", description = "How to resize your image", section = INVENTORY, position = 3)
    default ScalingMode inventoryScale()
    {
        return ScalingMode.CROP_TO_FILL;
    }

    @ConfigItem(keyName = "chatboxEnabled", name = "Enable chatbox image", description = "Apply a custom image behind chat text", section = CHATBOX, position = 0)
    default boolean chatboxEnabled()
    {
        return true;
    }

    @ConfigItem(keyName = "chatboxImagePath", name = "Chatbox image file", description = "Full path to a PNG or JPEG file (or use the plugin's Browse panel)", section = CHATBOX, position = 1)
    default String chatboxImagePath()
    {
        return "";
    }

    @Range(min = 0, max = 100)
    @ConfigItem(keyName = "chatboxOpacity", name = "Chatbox image strength", description = "Lower values make chat text easier to read", section = CHATBOX, position = 2)
    default int chatboxOpacity()
    {
        return 40;
    }

    @ConfigItem(keyName = "chatboxScale", name = "Chatbox image scaling", description = "How to resize your image", section = CHATBOX, position = 3)
    default ScalingMode chatboxScale()
    {
        return ScalingMode.CROP_TO_FILL;
    }
}

package com.customui.backgrounds;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;

import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.Filepath;

/** Simple browse buttons and thumbnails; other settings live in RuneLite configuration. */
final class PersonalUiBackgroundsPanel extends PluginPanel
{
    private final ConfigManager configManager;
    private final PersonalUiBackgroundsPlugin plugin;
    private final JLabel inventoryPreview = new JLabel();
    private final JLabel chatboxPreview = new JLabel();
    private final JLabel status = new JLabel();

    PersonalUiBackgroundsPanel(ConfigManager configManager, PersonalUiBackgroundsPlugin plugin)
    {
        this.configManager = configManager;
        this.plugin = plugin;
        setLayout(new BorderLayout());
        setBorder(BorderFactory.createEmptyBorder(12, 10, 10, 10));

        JPanel content = new JPanel();
        content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
        JLabel title = new JLabel("YOUR GAME, YOUR IMAGES");
        title.setFont(title.getFont().deriveFont(Font.BOLD, 13f));
        title.setAlignmentX(LEFT_ALIGNMENT);
        content.add(title);
        content.add(Box.createVerticalStrut(5));
        JLabel explainer = new JLabel("<html>Select PNG/JPG files on your PC. "
            + "Images stay on your computer.</html>");
        explainer.setAlignmentX(LEFT_ALIGNMENT);
        content.add(explainer);
        content.add(Box.createVerticalStrut(20));
        addImagePicker(content, "Inventory / side panel", "inventoryImagePath", inventoryPreview, 201, 276);
        content.add(Box.createVerticalStrut(20));
        addImagePicker(content, "Chatbox", "chatboxImagePath", chatboxPreview, 255, 75);
        content.add(Box.createVerticalStrut(14));

        JLabel note = new JLabel("<html>Adjust strength and cropping in the plugin's "
            + "configuration (wrench icon). On resizable modern chat, "
            + "the transparent UI may be unaffected.</html>");
        note.setAlignmentX(LEFT_ALIGNMENT);
        content.add(note);
        content.add(Box.createVerticalStrut(12));
        status.setAlignmentX(LEFT_ALIGNMENT);
        content.add(status);
        add(content, BorderLayout.NORTH);
        refresh();
    }

    private void addImagePicker(JPanel parent, String title, String configKey,
                                JLabel preview, int thumbnailWidth, int thumbnailHeight)
    {
        JLabel heading = new JLabel(title);
        heading.setFont(heading.getFont().deriveFont(Font.BOLD));
        heading.setAlignmentX(LEFT_ALIGNMENT);
        parent.add(heading);
        parent.add(Box.createVerticalStrut(7));

        preview.setHorizontalAlignment(SwingConstants.CENTER);
        preview.setPreferredSize(new Dimension(240, Math.min(160, thumbnailHeight)));
        preview.setMaximumSize(new Dimension(240, Math.min(160, thumbnailHeight)));
        preview.setBorder(BorderFactory.createLineBorder(new Color(98, 98, 98)));
        preview.setAlignmentX(LEFT_ALIGNMENT);
        parent.add(preview);
        parent.add(Box.createVerticalStrut(8));

        JButton choose = new JButton("Browse for image...");
        choose.setAlignmentX(LEFT_ALIGNMENT);

choose.addActionListener(e ->
{
    Filepath.Chooser picker = new Filepath.Chooser()
        .setIsOpen()
        .setAcceptsFiles()
        .setDialogTitle("Select " + title + " image")
        .addExtensionFilter("PNG or JPG images", "png", "jpg", "jpeg");

    List<Filepath> selected = picker.showDialog(this);
    if (selected == null || selected.isEmpty())
    {
        return;
    }

    try
    {
        plugin.saveSelectedImage(configKey, selected.get(0));
        refresh();
    }
    catch (IOException ex)
    {
        status.setText("<html><font color='#FF7777'>"
            + escapeHtml(ex.getMessage()) + "</font></html>");
    }
});

        parent.add(choose);

        JButton clear = new JButton("Clear image");
        clear.setAlignmentX(LEFT_ALIGNMENT);
        clear.addActionListener(e ->
        {
            configManager.setConfiguration(PersonalUiBackgroundsConfig.GROUP, configKey, "");
            refresh();
        });
        parent.add(Box.createVerticalStrut(4));
        parent.add(clear);
    }

    void refresh()
    {
        setPreview(inventoryPreview, configManager.getConfiguration(PersonalUiBackgroundsConfig.GROUP,
            "inventoryImagePath"));
        setPreview(chatboxPreview, configManager.getConfiguration(PersonalUiBackgroundsConfig.GROUP,
            "chatboxImagePath"));
        String error = plugin.getLastError();
        status.setText(error.isEmpty() ? "<html>Choose an image to begin.</html>"
            : "<html><font color='#FF7777'>" + escapeHtml(error) + "</font></html>");
    }

    private void setPreview(JLabel target, String path)
    {
        target.setIcon(null);
        if (path == null || path.trim().isEmpty())
        {
            target.setText("No image selected");
            return;
        }

try
{
    BufferedImage source = plugin.readSavedImage(path);

            if (source == null)
            {
                target.setText("Invalid image");
                return;
            }
            int maxW = 225;
            int maxH = 150;
            double scale = Math.min(maxW / (double) source.getWidth(), maxH / (double) source.getHeight());
            int width = Math.max(1, (int) Math.round(scale * source.getWidth()));
            int height = Math.max(1, (int) Math.round(scale * source.getHeight()));
            BufferedImage thumbnail = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
            Graphics2D g = thumbnail.createGraphics();
            try
            {
                g.setColor(Color.DARK_GRAY);
                g.fillRect(0, 0, width, height);
                g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
                g.drawImage(source, 0, 0, width, height, null);
            }
            finally
            {
                g.dispose();
                source.flush();
            }
            target.setText("");
            target.setIcon(new ImageIcon(thumbnail));
        }
        catch (IOException ex)
        {
            target.setText("Can't preview image");
        }
    }

    private static String escapeHtml(String text)
    {
        return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    static BufferedImage createIcon()
    {
        BufferedImage image = new BufferedImage(32, 32, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setColor(new Color(62, 47, 31));
            g.fillRoundRect(2, 3, 28, 26, 5, 5);
            g.setColor(new Color(229, 205, 151));
            g.drawRoundRect(2, 3, 27, 25, 5, 5);
            g.setColor(new Color(159, 215, 232));
            g.fillRect(6, 7, 20, 17);
            g.setColor(new Color(58, 126, 88));
            g.fillPolygon(new int[]{6, 12, 17, 25, 25, 6}, new int[]{24, 15, 20, 10, 24, 24}, 6);
            g.setColor(new Color(255, 217, 107));
            g.fillOval(19, 10, 5, 5);
        }
        finally
        {
            g.dispose();
        }
        return image;
    }
}

package com.customui.backgrounds;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.StandardCopyOption;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.SpriteID;
import net.runelite.api.SpritePixels;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.Filepath;


/**
 * Replaces only interface background sprites. Inventory icons and chat text
 * remain RuneScape-rendered elements ABOVE the custom backgrounds.
 * This plugin does not alter any game data or send images anywhere.
 */
@PluginDescriptor(
    name = "Personal UI Backgrounds",
    internalName = "personal-ui-backgrounds",
    description = "Choose local images for your inventory and chatbox backgrounds",
    tags = {"inventory", "chatbox", "custom", "background", "image"}
)
@SuppressWarnings("deprecation") // SpriteID names remain stable aliases in RuneLite.
public class PersonalUiBackgroundsPlugin extends Plugin
{
    private static final Logger log = LoggerFactory.getLogger(PersonalUiBackgroundsPlugin.class);
    private static final long MAX_FILE_SIZE_BYTES = 20L * 1024L * 1024L;
    private static final int MAX_IMAGE_DIMENSION = 8192;

    private static final int[] INVENTORY_SPRITES = {
        SpriteID.RS2_SIDE_PANEL_BACKGROUND,
        SpriteID.FIXED_MODE_SIDE_PANEL_BACKGROUND,
        SpriteID.RESIZEABLE_MODE_SIDE_PANEL_BACKGROUND
    };
    private static final int[] CHATBOX_SPRITES = {
        SpriteID.RS2_CHATBOX_BACKGROUND,
        SpriteID.CHATBOX
    };

    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ConfigManager configManager;
    @Inject private SpriteManager spriteManager;
    @Inject private ClientToolbar clientToolbar;
    @Inject private PersonalUiBackgroundsConfig config;

    private PersonalUiBackgroundsPanel panel;
    private NavigationButton navigationButton;
    private volatile boolean started;
    private volatile String lastError = "";

    // All maps below are accessed exclusively from the RuneLite client thread.
    private final Map<Integer, SpritePixels> installedSprites = new HashMap<>();
    private final Map<Integer, SpritePixels> replacedOverrides = new HashMap<>();
    private final Set<Integer> previouslyUnmapped = new HashSet<>();
    private final Map<Integer, BufferedImage> originalArtwork = new HashMap<>();

    @Provides
    PersonalUiBackgroundsConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(PersonalUiBackgroundsConfig.class);
    }

    @Override
    protected void startUp()
    {
        started = true;
        SwingUtilities.invokeLater(() ->
        {
            if (!started)
            {
                return;
            }
            panel = new PersonalUiBackgroundsPanel(configManager, this);
            navigationButton = NavigationButton.builder()
                .tooltip("Personal UI Backgrounds")
                .icon(PersonalUiBackgroundsPanel.createIcon())
                .priority(7)
                .panel(panel)
                .build();
            clientToolbar.addNavigation(navigationButton);
        });
        clientThread.invokeLater(this::reloadSprites);
    }

    @Override
    protected void shutDown()
    {
        started = false;
        clientThread.invokeLater(() ->
        {
            removeOurOverrides();
            originalArtwork.clear();
            replacedOverrides.clear();
            previouslyUnmapped.clear();
        });
        SwingUtilities.invokeLater(() ->
        {
            if (navigationButton != null)
            {
                clientToolbar.removeNavigation(navigationButton);
                navigationButton = null;
            }
            panel = null;
        });
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!PersonalUiBackgroundsConfig.GROUP.equals(event.getGroup()))
        {
            return;
        }
        clientThread.invokeLater(this::reloadSprites);
        SwingUtilities.invokeLater(() ->
        {
            if (panel != null)
            {
                panel.refresh();
            }
        });
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            clientThread.invokeLater(this::reloadSprites);
        }
    }

    public String getLastError()
    {
        return lastError;
    }

    private void reloadSprites()
    {
        if (!started)
        {
            return;
        }

        removeOurOverrides();
        lastError = "";

        // The whole image is read once per config change, not on every frame.
        if (config.inventoryEnabled() && !config.inventoryImagePath().trim().isEmpty())
        {
            try
            {
                BufferedImage image = readSavedImage(config.inventoryImagePath());
                for (int spriteId : INVENTORY_SPRITES)
                {
                    applySprite(spriteId, image, config.inventoryOpacity(), config.inventoryScale(), false);
                }
            }
            catch (IOException | IllegalArgumentException ex)
            {
                recordError("Inventory image: " + ex.getMessage());
            }
        }
        if (config.chatboxEnabled() && !config.chatboxImagePath().trim().isEmpty())
        {
            try
            {
                BufferedImage image = readSavedImage(config.chatboxImagePath());
                for (int spriteId : CHATBOX_SPRITES)
                {
                    applySprite(spriteId, image, config.chatboxOpacity(), config.chatboxScale(), true);
                }
            }
            catch (IOException | IllegalArgumentException ex)
            {
                recordError("Chatbox image: " + ex.getMessage());
            }
        }

        client.getWidgetSpriteCache().reset();
        SwingUtilities.invokeLater(() ->
        {
            if (panel != null)
            {
                panel.refresh();
            }
        });
    }

    private void recordError(String message)
    {
        log.warn(message);
        lastError = lastError.isEmpty() ? message : lastError + " | " + message;
    }


void saveSelectedImage(String configKey, Filepath selected) throws IOException
{
    final String fileName;
    if ("inventoryImagePath".equals(configKey))
    {
        fileName = "inventory-background.img";
    }
    else if ("chatboxImagePath".equals(configKey))
    {
        fileName = "chatbox-background.img";
    }
    else
    {
        throw new IOException("Invalid image selection");
    }

    // Validate the selected image before saving it.
    BufferedImage image = readFilepathImage(selected);
    image.flush();

    // Store the image inside this plugin's data directory.
    Filepath directory = getPluginDirectory();
    directory.createDirectories();
    selected.copyTo(directory.joinSegment(fileName),
        StandardCopyOption.REPLACE_EXISTING);

    configManager.setConfiguration(
        PersonalUiBackgroundsConfig.GROUP,
        configKey, fileName);
}

BufferedImage readSavedImage(String fileName) throws IOException
{
    if (!"inventory-background.img".equals(fileName)
        && !"chatbox-background.img".equals(fileName))
    {
        throw new IOException("Please select your image again using Browse");
    }

    Filepath file = getPluginDirectory().joinSegment(fileName);
    return readFilepathImage(file);
}

private static BufferedImage readFilepathImage(Filepath file) throws IOException
{
    if (!file.isFile())
    {
        throw new IOException("Image file not found");
    }

    if (file.size() > MAX_FILE_SIZE_BYTES)
    {
        throw new IOException("Image is over 20 MB; please use a smaller PNG/JPG");
    }

    try (InputStream stream = file.openInputStream())
    {
        BufferedImage photo = ImageIO.read(stream);
        if (photo == null)
        {
            throw new IOException("Unsupported image; use PNG or JPG");
        }

        if (photo.getWidth() > MAX_IMAGE_DIMENSION
            || photo.getHeight() > MAX_IMAGE_DIMENSION)
        {
            photo.flush();
            throw new IOException("Image is larger than 8192 px; resize it first");
        }

        return photo;
    }
}

    private void applySprite(int id, BufferedImage photo, int strength, ScalingMode scaleMode, boolean chatbox)
    {
        final int width;
        final int height;
        if (!chatbox)
        {
            // Resizable inventory is originally a small tiled sprite. Replacing it
            // with a 201x276 sprite prevents personal photos from repeating as tiles.
            width = id == SpriteID.RESIZEABLE_MODE_SIDE_PANEL_BACKGROUND ? 201 : 190;
            height = id == SpriteID.RESIZEABLE_MODE_SIDE_PANEL_BACKGROUND ? 276 : 261;
        }
        else
        {
            // Capture actual dimensions so classic and fixed gameframe artwork
            // keeps its intended size, including the decorative frame/borders.
            BufferedImage original = getOriginal(id);
            width = original != null ? original.getWidth() : (id == SpriteID.CHATBOX ? 519 : 479);
            height = original != null ? original.getHeight() : (id == SpriteID.CHATBOX ? 165 : 150);
        }

        BufferedImage original = getOriginal(id);
        int borderX = chatbox ? Math.min(10, width / 16) : 0;
        int borderTop = chatbox ? Math.min(8, height / 16) : 0;
        int borderBottom = chatbox ? Math.min(23, height / 6) : 0;
        BufferedImage output = BackgroundImageRenderer.render(original, photo, width, height,
            borderX, borderTop, borderX, borderBottom, strength, scaleMode,
            chatbox ? new Color(213, 193, 157) : new Color(59, 52, 38));
        int[] argb = output.getRGB(0, 0, width, height, null, 0, width);
        SpritePixels pixels = client.createSpritePixels(argb, width, height);
        if (pixels == null)
        {
            return;
        }

        Map<Integer, SpritePixels> overrides = client.getSpriteOverrides();
        if (!replacedOverrides.containsKey(id) && !previouslyUnmapped.contains(id))
        {
            if (overrides.containsKey(id))
            {
                replacedOverrides.put(id, overrides.get(id));
            }
            else
            {
                previouslyUnmapped.add(id);
            }
        }
        installedSprites.put(id, pixels);
        overrides.put(id, pixels);
    }

    private BufferedImage getOriginal(int id)
    {
        BufferedImage old = originalArtwork.get(id);
        if (old != null)
        {
            return old;
        }

        SpritePixels existing = replacedOverrides.get(id);
        if (existing == null && !previouslyUnmapped.contains(id))
        {
            existing = client.getSpriteOverrides().get(id);
        }
        if (existing != null)
        {
            old = existing.toBufferedImage();
        }
        else
        {
            // Cache source (archive, file 0). May be null before the login screen loads.
            old = spriteManager.getSprite(id, 0);
        }
        if (old != null && old.getWidth() > 0 && old.getHeight() > 0)
        {
            originalArtwork.put(id, old);
            return old;
        }
        return null;
    }

    private void removeOurOverrides()
    {
        if (installedSprites.isEmpty())
        {
            return;
        }
        Map<Integer, SpritePixels> overrides = client.getSpriteOverrides();
        for (Map.Entry<Integer, SpritePixels> entry : installedSprites.entrySet())
        {
            int id = entry.getKey();
            // Don't overwrite a different plugin's changes made after ours.
            if (overrides.get(id) != entry.getValue())
            {
                continue;
            }
            if (replacedOverrides.containsKey(id))
            {
                overrides.put(id, replacedOverrides.get(id));
            }
            else
            {
                overrides.remove(id);
            }
        }
        installedSprites.clear();
        client.getWidgetSpriteCache().reset();
    }
}

package com.customui.backgrounds;

public enum ScalingMode
{
    CROP_TO_FILL("Crop to fill"),
    FIT("Fit entire image"),
    STRETCH("Stretch to fit");

    private final String label;

    ScalingMode(String label)
    {
        this.label = label;
    }

    @Override
    public String toString()
    {
        return label;
